+/**
+ * Return a short advice label for a UV index.
+ * Valid indexes are finite, non-negative numbers; anything else returns null.
+ */
+export function uvAdvice(uv) {
+  if (typeof uv !== "number" || !Number.isFinite(uv) || uv < 0) return null;
+  if (uv <= 2) return "弱";
+  if (uv <= 5) return "中等";
+  if (uv <= 7) return "强";
+  return "极强";
+}
